package com.medicore.fulfillment.controller; import com.medicore.fulfillment.dto.*; import com.medicore.fulfillment.service.FulfillmentService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/fulfillment") public class FulfillmentController {private final FulfillmentService service; public FulfillmentController(FulfillmentService service){this.service=service;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public FulfillmentResponse create(@Valid @RequestBody FulfillmentRequest r){return service.create(r);} @GetMapping("/{id}") public FulfillmentResponse find(@PathVariable Long id){return service.find(id);} @PatchMapping("/{id}/status") public FulfillmentResponse status(@PathVariable Long id,@RequestParam String value){return service.status(id,value);}}
